INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('다자이후 오니스베', '太宰府天満宮 鬼すべ', '福岡県', '太宰府市', DATE '2027-01-07', DATE '2027-01-07', 2027, 33.519500, 130.535000, '다자이후 텐만궁에서 1000년 넘게 이어진 액막이 불 행사. 밤 21시 큰 소나무 장작에 불을 붙이고, 연기로 귀신을 몰아내는 쪽과 귀신 쪽이 겨룬다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나가사키 랜턴 페스티벌', '長崎ランタンフェスティバル', '長崎県', '長崎市', DATE '2027-02-05', DATE '2027-02-21', 2027, 32.741300, 129.875900, '중국 설(춘절)을 기념하는 행사에서 시작한 축제. 신치 차이나타운과 메가네바시 등 시내 중심을 약 1만 5천 개의 중국 등불이 물들이고, 황제 퍼레이드와 용춤이 열린다.', NULL, 'https://www.at-nagasaki.jp/lantern-festival', DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('하카타 돈타쿠', '博多どんたく港まつり', '福岡県', '福岡市博多区', DATE '2027-05-03', DATE '2027-05-04', 2027, 33.591000, 130.400000, '골든위크에 열리는 일본 최대급 시민 축제. 샤모지(주걱)를 두드리며 행진하는 퍼레이드와 시내 30곳 넘는 무대에서 이틀간 공연이 이어진다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나하 하리', '那覇ハーリー', '沖縄県', '那覇市', DATE '2027-05-03', DATE '2027-05-05', 2027, 26.229000, 127.672000, '용머리를 단 배(하리선)로 노 젓기를 겨루며 풍어와 바다 안전을 비는 오키나와 전통 행사. 이틀간 경조와 무대 공연, 불꽃놀이가 이어진다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('하카타 기온 야마카사', '博多祇園山笠', '福岡県', '福岡市博多区', DATE '2027-07-01', DATE '2027-07-15', 2027, 33.593000, 130.410600, '구시다 신사의 봉납 행사로 770년 넘게 이어진 하카타의 여름 축제. 15일 새벽 4시 59분, 무게 1톤의 가마(가키야마)를 메고 약 5km를 달리는 ''오이야마''가 절정이다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('오키나와 전도 에이사 마쓰리', '沖縄全島エイサーまつり', '沖縄県', '沖縄市', DATE '2027-08-27', DATE '2027-08-29', 2027, 26.333000, 127.800000, '오봉에 조상을 기리는 춤 ''에이사''를 섬 곳곳의 청년회가 모여 펼치는 축제. 큰북과 산신 가락에 맞춘 군무가 코자 운동공원을 울린다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나가사키 군치', '長崎くんち', '長崎県', '長崎市', DATE '2027-10-07', DATE '2027-10-09', 2027, 32.752000, 129.884000, '스와 신사의 가을 예대제. 중국·네덜란드 문화가 섞인 봉납 춤이 특징으로, 용춤(자오도리)과 배 모양 수레(고코부네)가 큰 박수를 받는다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나하 오쓰나히키 마쓰리', '那覇大綱挽まつり', '沖縄県', '那覇市', DATE '2027-10-08', DATE '2027-10-10', 2027, 26.216000, 127.680000, '길이 200m, 무게 40톤이 넘는 기네스 기록 줄다리기 줄을 1만 5천 명이 당기는 축제. 국도 58호선 구모지 교차로를 막고 줄을 당긴다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('가라쓰 군치', '唐津くんち', '佐賀県', '唐津市', DATE '2027-11-02', DATE '2027-11-04', 2027, 33.452000, 129.970000, '가라쓰 신사의 가을 예대제. 사자·도미·투구 모양의 거대한 칠기 수레(히키야마) 14대가 거리를 돌고, 3일 모래밭에 수레를 끌어들이는 장면이 하이라이트다.', NULL, NULL, DATE '2026-11-14', NULL);